# Parche de Inicio: Entrenar destacado + "Otras tareas" desplegable. Se ejecuta desde build.py (usa src, rep, re).
rep("const c=ctxFor(S.sel), d=c.d, ts=trainStats(), rows=[];","const c=ctxFor(S.sel), d=c.d, ts=trainStats(), tg=(typeof trainGroups==='function'?trainGroups():{gs:[],done:ts.done,total:ts.total,part:false}), rows=[];")
rep("s:(ts.total&&ts.done>=ts.total?'Completado ✓':'Fuerza, cardio y vuelta a la calma'),done:ts.done,total:ts.total}","s:(tg.total&&tg.done>=tg.total?'Completado ✓':tg.done?`${tg.done} de ${tg.total} partes listas`:tg.part?'En curso · sigue donde ibas':'Fuerza, cardio y vuelta a la calma'),done:tg.done,total:tg.total,part:tg.part&&!(tg.total&&tg.done>=tg.total)}")
_m=re.search(r'<div class="segbar">.*?(?=<div class="mini2">)',src,re.S)
assert _m
_new='''<div class="segbar">${tg.gs.map(x=>`<i style="background:${x.ok?'#2E9D6B':x.part?'#D9A441':'var(--line)'}"></i>`).join('')}</div>
   <div class="sub2">${(()=>{const er=rows.find(r=>r.p==='entrenar');if(!er)return isT?'Hoy empiezas con tus hábitos y tu respiración.':'';if(er.rest)return 'Hoy toca descanso. Camina y muévete suave.';return er.total&&er.done>=er.total?(isT?'Entrenamiento completo. Buen trabajo.':'Entrenamiento completo.'):(isT?'Llevas ':'Completaste ')+er.done+' de '+er.total+' partes del entreno'+(isT?' hoy':'')+'.';})()}</div>
   ${lessonCard()}<h2 class="h2">${isT?'Tu entreno de hoy':'Entreno del '+fmtL(S.sel).split(',')[0].toLowerCase()+' '+pd(S.sel).getDate()}</h2>
   ${(()=>{const others=act.filter(r=>r.p!=='entrenar'),er=rows.find(r=>r.p==='entrenar');
     const card=er?`<button class="tcard tmain${er.total&&er.done>=er.total?' tgreen':er.part?' tpart':''}" data-act="tab" data-v="entrenar" style="--c:${PIL.entrenar.c}"><span class="bar"></span><span class="tb"><small style="color:${PIL.entrenar.c}">${PIL.entrenar.n}</small><b>${er.t}</b><em>${er.s}</em></span><span class="st${er.total&&er.done>=er.total?' ok':''}">${er.total&&er.done>=er.total?'✓':er.rest?'–':er.part?'◐':'›'}</span></button>`:'';
     if(!others.length)return card;
     const fo=others.filter(r=>r.total&&r.done>=r.total).length,rowsH=others.map(r=>{const ok=r.total&&r.done>=r.total;return `<button class="orow" data-act="tab" data-v="${r.p}" style="--c:${PIL[r.p].c}"><i class="od"></i><span class="on">${PIL[r.p].n}</span><em>${r.done} de ${r.total}</em><span class="oc${ok?' ok':''}">${ok?'✓':'›'}</span></button>`;}).join('');
     return card+`<details class="otr"${(!er||OTROPEN)?' open':''}><summary><span><b>Otras tareas</b><small>${fo} de ${others.length} listas</small></span><span class="odots">${others.map(r=>{const ok=r.total&&r.done>=r.total;return `<i style="background:${ok?PIL[r.p].c:'var(--line)'}"></i>`;}).join('')}</span><i class="oc2">▾</i></summary>${rowsH}</details>`;})()}
   '''
src=src[:_m.start()]+_new+src[_m.end():]
src=src.replace('</style>','.tcard.tmain{padding:18px 14px 18px 0}.tcard.tmain b{font-size:18px}.tcard.tgreen{border-color:#2E9D6B!important;background:rgba(46,157,107,.14)!important}.tcard.tgreen .bar{background:#2E9D6B}.tcard.tgreen small{color:#2E9D6B!important}.tcard.tgreen .st.ok{background:#2E9D6B!important;border-color:#2E9D6B!important}.tcard.tpart{border-color:#D9A441!important}.tcard.tpart .bar{background:#D9A441}.tcard.tpart .st{color:#D9A441;border-color:#D9A441}\n.otr{background:var(--card);border:1px solid var(--line);border-radius:14px;margin:0 0 10px;overflow:hidden}.otr summary{list-style:none;display:flex;align-items:center;gap:10px;padding:11px 14px;cursor:pointer}.otr summary::-webkit-details-marker{display:none}.otr summary>span:first-child{flex:1;display:flex;flex-direction:column;gap:1px}.otr summary b{font-size:14px;font-weight:600}.otr summary small{font-size:12px;color:var(--gray)}.odots{display:flex;gap:4px}.odots i{width:8px;height:8px;border-radius:99px}.oc2{font-style:normal;color:var(--gray);transition:transform .2s}.otr[open] .oc2{transform:rotate(180deg)}\n.orow{width:100%;border:0;border-top:1px solid var(--line);box-shadow:none;border-radius:0;display:flex;align-items:center;gap:10px;text-align:left;padding:9px 14px;border-top:1px solid var(--line);background:transparent}.orow .od{width:8px;height:8px;border-radius:99px;background:var(--c);flex:none}.orow .on{flex:1;font-size:14px}.orow em{font-style:normal;font-size:12px;color:var(--gray)}.orow .oc{width:22px;height:22px;border-radius:99px;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--gray);flex:none}.orow .oc.ok{background:var(--c);border-color:var(--c);color:#fff}</style>',1)
